-- Reversibile (i player su «Simulazione» tornano a «Nessuno»): UPDATE "displays" SET "target_kind" = 'none' WHERE "target_kind" = 'simulation'; ALTER TABLE "displays" DROP CONSTRAINT "displays_target_check"; ALTER TABLE "displays" ALTER COLUMN "target_kind" DROP DEFAULT; ALTER TYPE "display_target" RENAME TO "display_target_old"; CREATE TYPE "display_target" AS ENUM('none', 'channel', 'match', 'fixture'); ALTER TABLE "displays" ALTER COLUMN "target_kind" TYPE "display_target" USING "target_kind"::text::"display_target"; ALTER TABLE "displays" ALTER COLUMN "target_kind" SET DEFAULT 'none'; DROP TYPE "display_target_old"; ALTER TABLE "displays" ADD CONSTRAINT "displays_target_check" CHECK (("displays"."target_kind" = 'match' or "displays"."match_id" is null) and ("displays"."target_kind" = 'fixture' or "displays"."client_fixture_id" is null));
